const KEY='aether.material-statistics.v1';
export function readStatistics(){try{const x=JSON.parse(localStorage.getItem(KEY)||'[]');return Array.isArray(x)?x.filter(v=>Number.isFinite(v.totalMs)).slice(-400):[];}catch{return[];}}
export function recordStatistic(record){const rows=[...readStatistics(),{...record,time:new Date().toISOString()}].slice(-400);try{localStorage.setItem(KEY,JSON.stringify(rows));}catch{}return rows;}
export function clearStatistics(){localStorage.removeItem(KEY);}
export function summarizeStatistics(rows){const groups=new Map();for(const r of rows){const key=[r.signature,r.size,r.adapter,r.backend,r.backend==='download'?(r.cache==='Cache Storage'?'cache':'network'):r.backend==='cpu'?'worker':r.cold?'cold':'warm'].join('|');if(!groups.has(key))groups.set(key,[]);groups.get(key).push(r);}return [...groups.values()].map(values=>{const a=values.map(v=>v.totalMs).sort((a,b)=>a-b),last=values.at(-1);return{...last,state:last.backend==='download'?(last.cache==='Cache Storage'?'cache':'network'):last.backend==='cpu'?'worker':last.cold?'cold':'warm',count:a.length,median:a.length%2?a[Math.floor(a.length/2)]:(a[a.length/2-1]+a[a.length/2])/2,p90:a[Math.min(a.length-1,Math.ceil(a.length*.9)-1)]};});}
export function deliveryAdvice(rows,{signature,size,adapter,budget=150}={}){const same=rows.filter(r=>r.signature===signature&&r.size===size&&r.adapter===adapter),groups=summarizeStatistics(same),gpu=groups.filter(g=>['gpu','hybrid'].includes(g.backend)&&!g.cold).sort((a,b)=>a.median-b.median)[0],download=groups.filter(g=>g.backend==='download').sort((a,b)=>a.median-b.median)[0],cpu=groups.find(g=>g.backend==='cpu');if(!same.length)return{choice:'Measure first',reason:'No measurements exist for this graph, resolution and adapter.'};if(gpu&&gpu.median<=budget&&(!download||gpu.median<download.median))return{choice:'Client GPU candidate',reason:`Warm GPU median ${gpu.median.toFixed(1)} ms is within the ${budget} ms budget.${download?' It is faster than the measured pack load.':' Measure a published pack before deciding.'}`};if(download)return{choice:'Prefer published pack',reason:`Measured pack load ${download.median.toFixed(1)} ms; ${gpu?'warm GPU '+gpu.median.toFixed(1)+' ms':'no warm GPU measurement yet'}.`};if(gpu)return{choice:'Prebake candidate',reason:`Warm GPU median ${gpu.median.toFixed(1)} ms exceeds the ${budget} ms interactive budget. Measure pack delivery next.`};return{choice:'Measure GPU / download',reason:cpu?`CPU median ${cpu.median.toFixed(1)} ms; a CPU-only result cannot establish GPU or network cost.`:'Collect comparable runs.'};}
